  grammar: [
    {"pat": "普通形 ＋ んだって", "desc": "Truyền đạt lại thông tin nghe được từ người khác trong hội thoại thân mật: “nghe nói là…”, “nghe bảo…đấy”. Là cách nói khẩu ngữ của 〜そうです（truyền đạt）.\n• V／イA thể thường: できる → できるんだって\n• ナA: だ → な: 大変だ → 大変なんだって\n• N: だ → な: 病気だ → 病気なんだって\nVới người trên hoặc khi trang trọng thì dùng 〜そうです.", "ex": [{"jp": "駅前（えきまえ）に新（あたら）しいデパートができるんだって。", "ro": "Ekimae ni atarashii depaato ga dekiru n datte.", "vi": "Nghe nói trước ga sắp mở một trung tâm thương mại mới đấy."}, {"jp": "マルコさん、来週（らいしゅう）引（ひ）っ越（こ）しなんだって。", "ro": "Maruko-san, raishuu hikkoshi nan datte.", "vi": "Nghe nói tuần sau anh Marco chuyển nhà đấy."}]},
    {"pat": "V thể từ điển ＋ のはどうですか", "desc": "Đưa ra đề xuất, gợi ý một phương án khi cùng bàn bạc: “… thì thế nào?”, “hay là mình … đi?”.\n• Lịch sự: V辞書形 ＋ のはどうですか\n• Thân mật: V辞書形 ＋ のはどう？\nPhân biệt: 〜たらどうですか thường là lời khuyên dành cho người nghe; 〜のはどうですか dùng để đưa ra một ý kiến, phương án (có thể bao gồm cả người nói).", "ex": [{"jp": "いろんな国（くに）の最近（さいきん）の映画（えいが）について調（しら）べて発表（はっぴょう）するのはどう？", "ro": "Ironna kuni no saikin no eiga ni tsuite shirabete happyou suru no wa dou?", "vi": "Hay là mình tìm hiểu về phim gần đây của nhiều nước rồi thuyết trình, cậu thấy sao?"}]},
    {"pat": "普通形 ＋ だけじゃなくて、＿＿も＿＿", "desc": "“Không chỉ … mà … cũng …”. Nêu một sự việc rồi bổ sung thêm sự việc khác; vế sau thường có も.\n• V／イA thể thường: 調べる → 調べるだけじゃなくて\n• ナA: だ → な: 大変だ → 大変なだけじゃなくて\n• N: bỏ だ: 学生だ → 学生だけじゃなくて\nだけじゃなくて là dạng văn nói của だけではなく（て）.", "ex": [{"jp": "インターネットで調（しら）べるだけじゃなくて、アンケートもしてみない？", "ro": "Intaanetto de shiraberu dake ja nakute, ankeeto mo shite minai?", "vi": "Không chỉ tra trên mạng, mình thử làm cả khảo sát nữa nhé?"}, {"jp": "一人暮（ひとりぐ）らしは大変（たいへん）なだけじゃなくて、おもしろいこともあります。", "ro": "Hitorigurashi wa taihen na dake ja nakute, omoshiroi koto mo arimasu.", "vi": "Sống một mình không chỉ vất vả mà cũng có những điều thú vị."}, {"jp": "日本語（にほんご）だけじゃなくて、日本（にほん）の文化（ぶんか）も学（まな）びたいです。", "ro": "Nihongo dake ja nakute, Nihon no bunka mo manabitai desu.", "vi": "Tôi muốn học không chỉ tiếng Nhật mà cả văn hóa Nhật Bản nữa."}]},
    {"pat": "イA-くないと／ナA・N ＋ じゃないと／V thể ない ＋ と、＿＿", "desc": "“Nếu không … thì (không) …”. Nêu điều kiện cần thiết; vế sau thường là thể phủ định hoặc một kết quả không mong muốn.\n• イA: 安い → 安くないと\n• ナA: 静かだ → 静かじゃないと\n• N: 市民だ → 市民じゃないと\n• V: 行く → 行かないと\nNói lửng 〜ないと。 (lược vế sau) mang nghĩa “phải … mới được”, VD もう帰らないと。", "ex": [{"jp": "もっと安（やす）くないと、誰（だれ）も買（か）いません。", "ro": "Motto yasukunai to, dare mo kaimasen.", "vi": "Nếu không rẻ hơn nữa thì sẽ chẳng ai mua đâu."}, {"jp": "さくら図書館（としょかん）は市民（しみん）じゃないと本（ほん）が借（か）りられません。", "ro": "Sakura toshokan wa shimin ja nai to hon ga kariraremasen.", "vi": "Ở thư viện Sakura, nếu không phải cư dân thành phố thì không mượn sách được."}, {"jp": "急（いそ）いで行（い）かないと、コンサートに間（ま）に合（あ）いません。", "ro": "Isoide ikanai to, konsaato ni maniaimasen.", "vi": "Nếu không đi nhanh thì sẽ không kịp buổi hòa nhạc."}]},
    {"pat": "V thể て ＋ きます", "desc": "Diễn tả sự thay đổi diễn ra dần dần từ quá khứ cho đến hiện tại (thường dùng dạng 〜てきました). Hay đi với 増える、減る、変わる、〜くなる、だんだん、少しずつ.\n• 減ります → 減ってきました\n• 増えます → 増えてきました\n• 寒くなります → 寒くなってきました", "ex": [{"jp": "たばこを吸（す）う人（ひと）が減（へ）ってきました。", "ro": "Tabako o suu hito ga hette kimashita.", "vi": "Số người hút thuốc lá đã giảm dần."}]},
    {"pat": "V thể て ＋ いきます", "desc": "Diễn tả sự thay đổi sẽ tiếp diễn từ bây giờ về sau. Hay đi với これから、これからも、ますます.\n• 上がります → 上がっていきます\n• 増えます → 増えていきます\nPhân biệt: 〜てきました = thay đổi từ trước đến nay; 〜ていきます = thay đổi từ nay về sau.", "ex": [{"jp": "これから、野菜（やさい）の値段（ねだん）は上（あ）がっていくと思（おも）います。", "ro": "Korekara, yasai no nedan wa agatte iku to omoimasu.", "vi": "Tôi nghĩ từ giờ trở đi giá rau sẽ còn tăng lên."}]},
    {"pat": "普通形 ＋ ために、＿＿（nguyên nhân）", "desc": "“Do … nên …”. Nêu nguyên nhân dẫn đến một kết quả (thường là không mong muốn); sắc thái trang trọng, hay dùng trong tin tức, thông báo.\n• V／イA thể thường: 落とした → 落としたために\n• ナA: だ → な: 不便だ → 不便なために\n• N: だ → の: 事故だ → 事故のために\nVế sau không dùng câu mệnh lệnh, nhờ vả, ý chí. Phân biệt với ために chỉ mục đích (V辞書形／Nの ＋ ために, “để…”).", "ex": [{"jp": "落（お）としたために、スマートフォンの画面（がめん）が割（わ）れてしまいました。", "ro": "Otoshita tame ni, sumaatofon no gamen ga warete shimaimashita.", "vi": "Vì làm rơi nên màn hình điện thoại đã bị vỡ mất."}, {"jp": "事故（じこ）のために、電車（でんしゃ）が遅（おく）れています。", "ro": "Jiko no tame ni, densha ga okurete imasu.", "vi": "Do tai nạn nên tàu điện đang bị chậm."}]},
    {"pat": "Tóm tắt", "desc": "• 普通形 ＋ んだって → nghe nói là… (văn nói)\n• V辞書形 ＋ のはどうですか → … thì thế nào? (đề xuất)\n• 普通形 ＋ だけじゃなくて、〜も → không chỉ … mà … cũng\n• 〜くないと／じゃないと／Vないと → nếu không … thì …\n• Vてきました → đã thay đổi dần đến nay\n• Vていきます → sẽ thay đổi dần từ nay về sau\n• 普通形 ＋ ために（ナA な／N の） → do … nên … (nguyên nhân)", "ex": []}
  ],

